#include <bits/stdc++.h>
using namespace std;

#define rep(i, s, t) for(int i = (s); i <= (t); ++i)
#define drep(i, s, t) for(int i = (t); i >= (s); --i)

int read_int() {
    char c; int x = 0, sign = 1;
    c = getchar();
    while(c < '0' || c > '9') {
        if(c == '-') sign = -1;
        c = getchar();
    }
    while(c >= '0' && c <= '9') {
        x = x * 10 + c - '0';
        c = getchar();
    }
    return x * sign;
}

const int N = 505;
int n, m, P, maxn, fac[N], inv[N], F[N][N], G[N][N], f[N], g[N];

int fast_pow(int base, int exp) {
    int result = 1;
    while(exp > 0) {
        if(exp & 1) result = (long long)result * base % P;
        base = (long long)base * base % P;
        exp >>= 1;
    }
    return result;
}

int comb(int x, int y) {
    if(x < y || y < 0) return 0;
    return (long long)fac[x] * inv[y] % P * inv[x - y] % P;
}

int sum_series(int x) {
    return x * (x + 1) / 2;
}

int main() {
    n = read_int(); m = read_int(); P = read_int();
    maxn = n + 1;
    fac[0] = inv[0] = 1;
    rep(i, 1, maxn) {
        fac[i] = (long long)fac[i - 1] * i % P;
    }
    rep(i, 1, maxn) {
        inv[i] = fast_pow(fac[i], P - 2);
    }
    f[0] = 1;
    rep(i, 1, m) {
        for(int j = 0; j < i; ++j) {
            f[i] = (f[i] + (long long)f[j] * f[i - 1 - j] % P * comb(i - 1, j) ) % P;
            g[i] = (g[i] + ( ((long long)g[j] * f[i - 1 - j] % P + (long long)f[j] * g[i - 1 - j] % P) * (i + 1) % P
                + (long long)f[j] * f[i - 1 - j] % P * (sum_series(j) + sum_series(i - 1 - j)) % P) * comb(i - 1, j) ) % P;
        }
        f[i] = (long long)f[i] * (i + 1) % P;
    }
    memset(F, 0, sizeof(F));
    memset(G, 0, sizeof(G));
    F[0][0] = 1;
    rep(j, 0, n) F[0][j] = 1;
    rep(i, 1, m) {
        F[i][i] = f[i];
        G[i][i] = g[i];
        for(int j = i + 1; j <= n; ++j) {
            F[i][j] = F[i][j - 1];
            G[i][j] = G[i][j - 1];
            for(int l = 1; l <= i; ++l) {
                F[i][j] = (F[i][j] + (long long)F[i - l][j - 1 - l] * f[l] % P * comb(i, l)) % P;
                G[i][j] = (G[i][j] + ((long long)G[i - l][j - 1 - l] * f[l] % P + (long long)F[i - l][j - 1 - l] * g[l] % P) * comb(i, l)) % P;
            }
        }
    }
    printf("%lld\n", G[m][n]);
    return 0;
}
